  ('edge_adj_gare_forum_walk', 'adj_gare_routiere', 'adj_forum', true, 'walk', 5, 0, 'Marche Adjamé Gare ➔ Forum', 'Traverse l''allée marchande piétonne pour entrer dans l''enceinte du grand Forum des Marchés.'),
